"""Measure straight intersection crossing and lane identity; no statutory verdict."""
import hashlib
import json
import math
from pathlib import Path


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def rows(path):
    path=Path(path)
    if not path.is_file():raise ValueError('Missing required source: '+path.name)
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def point(value,label):
    if not isinstance(value,list) or len(value)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in value):
        raise ValueError('Invalid Native '+label)
    return value


def overlap(body):
    return max(p[0] for p in body)>=-7 and min(p[0] for p in body)<=7 and \
           max(p[1] for p in body)>=-7 and min(p[1] for p in body)<=7


def measure_crossing(samples_path,geometry_path):
    samples_path=Path(samples_path);geometry_path=Path(geometry_path)
    if not geometry_path.is_file():raise ValueError('Missing required source: '+geometry_path.name)
    geometry=json.loads(geometry_path.read_text())
    if not isinstance(geometry.get('native_map_sha256'),str) or len(geometry['native_map_sha256'])!=64:
        raise ValueError('Native map hash missing')
    expected={'approach_road_id':1,'straight_connector_road_id':14,
              'straight_destination_road_id':2,'right_only_lane_id':-2,
              'adjacent_through_lane_id':-1,'intersection_native_xy_bounds_m':[-7,-7,7,7]}
    if any(geometry.get(key)!=value for key,value in expected.items()):
        raise ValueError('Native road/lane survey differs from authored crossing')
    samples=rows(samples_path)
    if len(samples)<4:raise ValueError('Too few Native samples')
    previous_frame=-1;previous_time=-math.inf;approach=[];inside=[];exits=[]
    for sample in samples:
        frame=sample.get('native_frame');time=sample.get('time_s')
        if type(frame) is not int or frame<=previous_frame or type(time) not in (int,float) or not math.isfinite(time) or time<=previous_time:
            raise ValueError('Native frame/time sequence invalid')
        previous_frame=frame;previous_time=time
        body=sample.get('native_body_xy_m')
        if not isinstance(body,list) or len(body)!=4:raise ValueError('Complete Native body missing')
        for vertex in body:point(vertex,'body vertex')
        forward=point(sample.get('native_forward_xy'),'heading')
        if abs(math.hypot(*forward)-1)>.01:raise ValueError('Native heading not unit length')
        if any(type(sample.get(key)) is not int for key in ('native_road_id','native_lane_id')):
            raise ValueError('Native road/lane identity missing')
        if sample['native_road_id']==1 and max(p[0] for p in body)<-7:
            approach.append(sample)
        if sample['native_road_id']==14 and overlap(body):inside.append(sample)
        if sample['native_road_id']==2 and min(p[0] for p in body)>7:exits.append(sample)
    if len(approach)<2 or not inside or not exits:
        raise ValueError('Approach, intersection crossing and complete exit not all observed')
    if approach[-1]['native_frame']>=inside[0]['native_frame'] or inside[-1]['native_frame']>=exits[0]['native_frame']:
        raise ValueError('Crossing phase order invalid')
    if any(row['native_forward_xy'][0]<.95 for row in (approach[0],inside[0],exits[-1])):
        raise ValueError('Straight heading through intersection missing')
    lanes={row['native_lane_id'] for row in approach+inside+exits}
    if lanes not in ({-2},{-1}):raise ValueError('Lane identity changed during crossing')
    observed_lane=next(iter(lanes))
    fraction=sum(row['native_lane_id']==-2 for row in inside)/len(inside)
    return {'format':'c382389-right-only-lane-crossing-v1',
            'approach_window_s':[approach[0]['time_s'],approach[-1]['time_s']],
            'intersection_window_s':[inside[0]['time_s'],inside[-1]['time_s']],
            'complete_exit_window_s':[exits[0]['time_s'],exits[-1]['time_s']],
            'observed_approach_lane_id':observed_lane,
            'right_only_lane_intersection_sample_fraction':fraction,
            'straight_through_from_right_only_lane_observed':observed_lane==-2 and fraction==1,
            'right_only_lane_design_native_verified':geometry.get('right_only_lane_design_native_verified') is True,
            'source_hashes':{samples_path.name:sha(samples_path),geometry_path.name:sha(geometry_path)},
            'scope':'sampled Native body/lane IDs through a complete straight crossing; design, intersample occupancy and legal outcome unverified'}

"""Source-bound fallback decisions for both straight-crossing lane probes."""
import hashlib
import json
import math
from pathlib import Path


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def point(value):
    if not isinstance(value,list) or len(value)!=2 or any(
            type(v) not in (int,float) or not math.isfinite(v) for v in value):
        raise ValueError('Invalid Native or requested route point')
    return value


def distance(p,a,b):
    dx,dy=b[0]-a[0],b[1]-a[1]
    length2=dx*dx+dy*dy
    if length2==0:raise ValueError('Degenerate requested route segment')
    t=max(0,min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/length2))
    return math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy)


def evaluate(samples_path,geometry_path,map_audit_path,pixel_audit_path,video_path,
             requested_route_xy_m,requested_lane_id):
    """Evaluate three distinct triggers from an original-attempt source packet.

    A synthetic packet tests the calculation, but cannot establish the claimed
    Native map readback or original-pixel provenance.
    """
    paths=[Path(p) for p in (samples_path,geometry_path,map_audit_path,pixel_audit_path,video_path)]
    if any(not p.is_file() for p in paths):raise ValueError('Missing trigger source')
    if requested_lane_id not in (-2,-1):
        raise ValueError('Unknown requested lane')
    samples=[json.loads(line) for line in paths[0].read_text().splitlines() if line.strip()]
    if len(samples)<4:raise ValueError('Too few original Native samples')
    geometry=json.loads(paths[1].read_text())
    mapping=json.loads(paths[2].read_text())
    pixels=json.loads(paths[3].read_text())
    if not isinstance(geometry.get('native_map_sha256'),str) or len(geometry['native_map_sha256'])!=64:
        raise ValueError('Native geometry map hash missing')
    if mapping.get('source_kind')!='native_map_readback' or type(mapping.get('connected_requested_lane_link')) is not bool:
        raise ValueError('Native lane-link audit missing')
    if (mapping.get('native_samples_sha256')!=sha(paths[0]) or
        mapping.get('road_geometry_sha256')!=sha(paths[1]) or
        mapping.get('native_map_sha256')!=geometry['native_map_sha256']):
        raise ValueError('Native map audit source hash mismatch')
    if pixels.get('source_kind')!='original_camera_pixels' or pixels.get('native_samples_sha256')!=sha(paths[0]) or pixels.get('video_sha256')!=sha(paths[4]):
        raise ValueError('Pixel audit source hash mismatch')
    visible,total=pixels.get('full_body_and_lane_marking_visible_frames'),pixels.get('approach_frames')
    if type(visible) is not int or type(total) is not int or total<1 or not 0<=visible<=total:
        raise ValueError('Invalid original-pixel visibility count')
    route=[point(p) for p in requested_route_xy_m]
    if len(route)<2:raise ValueError('Requested route incomplete')
    errors=[];completed=False;prior_frame=-1;prior_time=-math.inf
    for row in samples:
        frame,time=row.get('native_frame'),row.get('time_s')
        if type(frame) is not int or frame<=prior_frame or type(time) not in (int,float) or not math.isfinite(time) or time<=prior_time:
            raise ValueError('Native frame/time sequence invalid')
        prior_frame,prior_time=frame,time
        center=point(row.get('native_center_xy_m'))
        forward=point(row.get('native_forward_xy'))
        if abs(math.hypot(*forward)-1)>.01:raise ValueError('Native heading not unit length')
        body=row.get('native_body_xy_m')
        if not isinstance(body,list) or len(body)!=4:raise ValueError('Complete Native body missing')
        body=[point(p) for p in body]
        if -10<=center[0]<=7:
            errors.append(min(distance(center,a,b) for a,b in zip(route,route[1:])))
        if (time<=24 and row.get('native_lane_id')==requested_lane_id and
            row.get('native_road_id')==2 and min(p[0] for p in body)>7 and forward[0]>.95):
            completed=True
    if not errors:raise ValueError('No observed connector-entry tracking window')
    maximum=max(errors);fraction=visible/total
    return {'fallback1':not mapping['connected_requested_lane_link'] or not completed,
            'fallback2':maximum>.35,'fallback3':fraction<.95,
            'metrics':{'connected_requested_lane_link':mapping['connected_requested_lane_link'],
                       'full_body_requested_exit_observed_by_24s':completed,
                       'maximum_connector_entry_route_error_m':maximum,
                       'approach_pixel_visible_fraction':fraction},
            'source_hashes':{p.name:sha(p) for p in paths},
            'scope':'Source-bound CPU trigger logic; synthetic packets are not physical observations'}

import unittest
from engineering import parameters


class CandidateKnobsTest(unittest.TestCase):
    def test_fallbacks_change_separate_knobs_and_hold_case_context(self):
        for suffix in ('reference','contrast'):
            plans={name:parameters(suffix,name) for name in
                   ('primary','fallback1','fallback2','fallback3')}
            base=plans['primary']
            for name,plan in plans.items():
                for key in ('law_id','cell_id','actor','duration_s','rate_hz','comparison_approach_y_m'):
                    self.assertEqual(plan[key],base[key],(suffix,name,key))
            self.assertNotEqual(plans['fallback1']['native_route_xy_m'],base['native_route_xy_m'])
            self.assertEqual(plans['fallback1']['controller_knobs'],base['controller_knobs'])
            self.assertEqual(plans['fallback1']['cameras'],base['cameras'])
            self.assertEqual(plans['fallback2']['native_route_xy_m'],base['native_route_xy_m'])
            self.assertNotEqual(plans['fallback2']['controller_knobs'],base['controller_knobs'])
            self.assertEqual(plans['fallback2']['cameras'],base['cameras'])
            self.assertEqual(plans['fallback3']['native_route_xy_m'],base['native_route_xy_m'])
            self.assertEqual(plans['fallback3']['controller_knobs'],base['controller_knobs'])
            self.assertNotEqual(plans['fallback3']['cameras'],base['cameras'])


if __name__=='__main__':unittest.main()
